import { BrowserRouter, Routes, Route } from "react-router-dom";

import LoginPage from "./LoginPage";
import PredictionForm from "./components/PredictionForm";

function App() {

  return (

    <BrowserRouter>

      <Routes>

        <Route
          path="/"
          element={<LoginPage />}
        />

        <Route
          path="/predict"
          element={<PredictionForm />}
        />

      </Routes>

    </BrowserRouter>

  );
}

export default App;
